"use strict";

const show = require ("../more/show");
const getType = require ("../more/getType");

// A lazy computation that reads an environment `r` and then fails with an
// `e` or succeeds with an `a`.  Nothing runs until `fork (reject, resolve,
// env)`; that call may return a function that cancels the computation.

// Rej :: e -> ()
// Res :: a -> ()
// RTask :: ((Rej, Res, r) -> *) -> RTask r e a
function RTask(computation) {
  // RTask#fork :: RTask r e a ~> (e -> b, a -> b, r) -> * | (() -> ())
  this.fork = computation;
}

// task :: ((Rej, Res, r) -> *) -> RTask r e a
function task(computation) {
  return new RTask (computation);
}

// A cancel function, also when the computation returned something else.
// asCancel :: a -> (() -> ())
const asCancel = returned => (typeof returned === "function" ? returned : () => {});

// task.of :: a -> RTask r e a
task.of = RTask.of = function (value) {
  return task ((_reject, resolve) => resolve (value));
};

// task.reject :: e -> RTask r e a
task.reject = RTask.reject = function (failure) {
  return task (reject => reject (failure));
};

// The environment itself, or something read from it.
// task.ask :: () -> RTask r e r
// task.ask :: (r -> a) -> RTask r e a
// ::ignore-function
task.ask = RTask.ask = function (read) {
  return task ((_reject, resolve, env) => resolve (read === undefined ? env : read (env)));
};

// Lazy: the promise is only created when the task is forked, and after a
// cancel its outcome is ignored.
// task.fromPromise :: (* -> Promise e a) -> * -> RTask r e a
task.fromPromise = RTask.fromPromise = function (start) {
  return input => task ((reject, resolve) => {
    let cancelled = false;
    start (input).then (
      value => { if (!cancelled) resolve (value); },
      failure => { if (!cancelled) reject (failure); });
    return () => { cancelled = true; };
  });
};

// task.isRTask :: a -> Boolean
task.isRTask = RTask.isRTask = function (candidate) {
  return getType (candidate) === "RTask";
};

// task.name :: String
Object.defineProperty (task, "name", { value: "RTask" });

// RTask#@@type :: String
RTask.prototype["@@type"] = "RTask";

// RTask#map :: RTask r e a ~> (a -> b) -> RTask r e b
RTask.prototype.map = function (f) {
  return task ((reject, resolve, env) => this.fork (reject, value => resolve (f (value)), env));
};

// RTask#mapLeft :: RTask r e a ~> (e -> c) -> RTask r c a
RTask.prototype.mapLeft = function (f) {
  return task ((reject, resolve, env) => this.fork (failure => reject (f (failure)), resolve, env));
};

// Runs the next task with the same environment; cancelling stops whichever
// of the two is running.
// RTask#chain :: RTask r e a ~> (a -> RTask r e b) -> RTask r e b
RTask.prototype.chain = function (f) {
  return task ((reject, resolve, env) => {
    let cancelNext = () => {};
    const cancelFirst = asCancel (this.fork (reject, value => {
      cancelNext = asCancel (f (value).fork (reject, resolve, env));
    }, env));
    return () => {
      cancelFirst ();
      cancelNext ();
    };
  });
};

// Recovers from a failure with another task.
// RTask#chainLeft :: RTask r e a ~> (e -> RTask r e a) -> RTask r e a
RTask.prototype.chainLeft = function (f) {
  return task ((reject, resolve, env) =>
    this.fork (failure => f (failure).fork (reject, resolve, env), resolve, env));
};

// RTask#show :: RTask r e a ~> () -> String
RTask.prototype.show = function () {
  return "RTask (fork :: (e -> (), a -> (), r) -> ())";
};

module.exports = task;
